import java.util.Arrays;

public class ArrayTrimmer {
    /** 
     * Trim the elements of the given String array, calling <code>String.trim()</code> on each of them.
     * @param array the original String array
     * @return the resulting array (of the same size) with trimmed elements
     */
    public static String[] trimArrayElements(String[] array) {
        if (array == null) {
            return null;
        }
        String[] trimmedArray = new String[array.length];
        for (int i = 0; i < array.length; i++) {
            trimmedArray[i] = array[i] != null ? array[i].trim() : null;
        }
        return trimmedArray;
    }

    public static void main(String[] args) {
        String[] testArray = {"  hello  ", " world ", "  java  "};
        String[] trimmedArray = trimArrayElements(testArray);
        System.out.println(Arrays.toString(trimmedArray)); // Output: [hello, world, java]
    }
}

import java.util.Arrays;

public class ArrayUtils {
    /** 
     * <p>Checks whether two arrays are the same length, treating <code>null</code> arrays as length <code>0</code>.</p>
     * @param array1 the first array, may be <code>null</code>
     * @param array2 the second array, may be <code>null</code>
     * @return <code>true</code> if length of arrays matches, treating<code>null</code> as an empty array
     */
    public static boolean isSameLength(final byte[] array1, final byte[] array2) {
        int length1 = (array1 == null) ? 0 : array1.length;
        int length2 = (array2 == null) ? 0 : array2.length;
        return length1 == length2;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(isSameLength(null, null)); // true
        System.out.println(isSameLength(new byte[]{}, new byte[]{})); // true
        System.out.println(isSameLength(new byte[]{1, 2, 3}, new byte[]{4, 5, 6})); // true
        System.out.println(isSameLength(new byte[]{1, 2, 3}, new byte[]{4, 5})); // false
        System.out.println(isSameLength(null, new byte[]{})); // true
        System.out.println(isSameLength(new byte[]{1, 2}, null)); // false
    }
}

import java.util.Stack;

public class OutputFrameStack {
    private Stack<Integer> stack = new Stack<>();

    /** 
     * Pops an abstract type from the output frame stack and returns its value.
     * @return the abstract type that has been popped from the output frame stack.
     */
    private int pop() {
        if (stack.isEmpty()) {
            throw new IllegalStateException("Stack is empty");
        }
        return stack.pop();
    }

    public static void main(String[] args) {
        OutputFrameStack ofStack = new OutputFrameStack();
        ofStack.stack.push(1);
        ofStack.stack.push(2);
        System.out.println(ofStack.pop()); // Should print 2
        System.out.println(ofStack.pop()); // Should print 1
    }
}

import java.util.Objects;

public class BooleanArrayConverter {

    /** 
     * <p>Converts an array of object Booleans to primitives.</p> <p>This method returns <code>null</code> for a <code>null</code> input array.</p>
     * @param array  a <code>Boolean</code> array, may be <code>null</code>
     * @return a <code>boolean</code> array, <code>null</code> if null array input
     * @throws NullPointerException if array content is <code>null</code>
     */
    public static boolean[] toPrimitive(final Boolean[] array) {
        if (array == null) {
            return null;
        }
        final boolean[] result = new boolean[array.length];
        for (int i = 0; i < array.length; i++) {
            result[i] = Objects.requireNonNull(array[i], "Array content cannot be null");
        }
        return result;
    }

    public static void main(String[] args) {
        Boolean[] booleanArray = {Boolean.TRUE, Boolean.FALSE, Boolean.TRUE};
        boolean[] primitiveArray = toPrimitive(booleanArray);
        for (boolean b : primitiveArray) {
            System.out.println(b);
        }
    }
}

