public class StackMapFrameVisitor {

    private List<Object> currentFrame;

    public StackMapFrameVisitor() {
        this.currentFrame = new ArrayList<>();
    }

    public int visitFrameStart(final int offset, final int numLocal, final int numStack) {
        currentFrame.add(offset);
        currentFrame.add(numLocal);
        currentFrame.add(numStack);
        return 3; // Index of the next element to be written in this frame
    }

    public static void main(String[] args) {
        StackMapFrameVisitor visitor = new StackMapFrameVisitor();
        int nextIndex = visitor.visitFrameStart(10, 5, 2);
        System.out.println("Next index to write: " + nextIndex);
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int capacity;
    private int position;

    public ByteVector(int initialCapacity) {
        this.data = new byte[initialCapacity];
        this.capacity = initialCapacity;
        this.position = 0;
    }

    private void enlarge(final int size) {
        int newSize = position + size;
        if (newSize > capacity) {
            int newCapacity = Math.max(newSize, capacity * 2);
            data = Arrays.copyOf(data, newCapacity);
            capacity = newCapacity;
        }
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector(10);
        bv.enlarge(15);
        System.out.println(bv.capacity); // Should print at least 20
    }
}

