class TreeNode<T> {
    T value;
    TreeNode<T> left;
    TreeNode<T> right;

    TreeNode(T value) {
        this.value = value;
        left = null;
        right = null;
    }
}

public class TreeRotator {

    /** 
     * Performs a right node rotation.
     * @param node a node to rotate
     * @return a new parent of the {@code node}
     */
    private TreeNode<T> rotateRight(TreeNode<T> node) {
        if (node == null || node.left == null) {
            return node;
        }
        TreeNode<T> newRoot = node.left;
        node.left = newRoot.right;
        newRoot.right = node;
        return newRoot;
    }

    public static void main(String[] args) {
        TreeRotator rotator = new TreeRotator();
        TreeNode<Integer> root = new TreeNode<>(3);
        root.left = new TreeNode<>(2);
        root.left.left = new TreeNode<>(1);

        TreeNode<Integer> newRoot = rotator.rotateRight(root);
        System.out.println("New root value: " + newRoot.value); // Should print 2
        System.out.println("New root right value: " + newRoot.right.value); // Should print 3
        System.out.println("New root right left value: " + newRoot.right.left.value); // Should print 1
    }
}

