public class FilenameUtils {

    public static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }
        int lastUnixPos = filename.lastIndexOf('/');
        int lastWindowsPos = filename.lastIndexOf('\\');
        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static void main(String[] args) {
        System.out.println(indexOfLastSeparator("path/to/file.txt")); // Output: 8
        System.out.println(indexOfLastSeparator("C:\\path\\to\\file.txt")); // Output: 12
        System.out.println(indexOfLastSeparator("file.txt")); // Output: -1
        System.out.println(indexOfLastSeparator(null)); // Output: -1
    }
}

import java.nio.charset.StandardCharsets;

public class HeaderParser {

    /** 
     * Skips bytes until the end of the current line.
     * @param headerPart The headers, which are being parsed.
     * @param end Index of the last byte, which has yet been processed.
     * @return Index of the \r\n sequence, which indicates end of line.
     */
    private int parseEndOfLine(String headerPart, int end) {
        byte[] bytes = headerPart.getBytes(StandardCharsets.UTF_8);
        for (int i = end; i < bytes.length - 1; i++) {
            if (bytes[i] == '\r' && bytes[i + 1] == '\n') {
                return i;
            }
        }
        return -1; // Return -1 if no \r\n sequence is found
    }

    public static void main(String[] args) {
        HeaderParser parser = new HeaderParser();
        String header = "Header1: Value1\r\nHeader2: Value2\r\n";
        int endIndex = parser.parseEndOfLine(header, 0);
        System.out.println("End of line index: " + endIndex);
    }
}

