        System.out.println(lastIndexOf("hello world", "hello")); // Output: 0
        System.out.println(lastIndexOf("hello world", "test"));  // Output: -1
        System.out.println(lastIndexOf(null, "test"));          // Output: -1
        System.out.println(lastIndexOf("hello world", null));    // Output: -1
    }
}

