import java.io.File;
import java.io.IOException;

public class FileDeletionUtility {

    /** 
     * Schedules a file to be deleted when JVM exits. If file is directory delete it and all sub-directories.
     * @param file  file or directory to delete, must not be {@code null}
     * @throws NullPointerException if the file is {@code null}
     * @throws IOException in case deletion is unsuccessful
     */
    public static void forceDeleteOnExit(File file) throws IOException {
        if (file == null) {
            throw new NullPointerException("File must not be null");
        }
        if (file.isDirectory()) {
            deleteDirectoryOnExit(file);
        } else {
            file.deleteOnExit();
        }
    }

    private static void deleteDirectoryOnExit(File directory) throws IOException {
        File[] files = directory.listFiles();
        if (files != null) {
            for (File file : files) {
                if (file.isDirectory()) {
                    deleteDirectoryOnExit(file);
                } else {
                    file.deleteOnExit();
                }
            }
        }
        directory.deleteOnExit();
    }

    public static void main(String[] args) {
        // Example usage
        File tempFile = new File("temp.txt");
        try {
            tempFile.createNewFile();
            forceDeleteOnExit(tempFile);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import javax.swing.*;
import java.util.logging.LogRecord;
import java.util.logging.Handler;
import java.util.logging.LogManager;
import java.util.logging.Logger;

public class LogTableHandler extends Handler {

    private final JTextArea logTextArea;

    public LogTableHandler(JTextArea logTextArea) {
        this.logTextArea = logTextArea;
    }

    @Override
    public void publish(LogRecord lr) {
        addMessage(lr);
    }

    @Override
    public void flush() {
        // No-op
    }

    @Override
    public void close() throws SecurityException {
        // No-op
    }

    public void addMessage(final LogRecord lr) {
        SwingUtilities.invokeLater(new Runnable() {
            @Override
            public void run() {
                logTextArea.append(lr.getMessage() + "\n");
            }
        });
    }

    public static void main(String[] args) {
        JFrame frame = new JFrame("LogTable Example");
        JTextArea logTextArea = new JTextArea(20, 40);
        logTextArea.setEditable(false);

        LogTableHandler handler = new LogTableHandler(logTextArea);
        Logger logger = LogManager.getLogManager().getLogger(Logger.GLOBAL_LOGGER_NAME);
        logger.addHandler(handler);

        frame.add(new JScrollPane(logTextArea));
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.pack();
        frame.setVisible(true);

        logger.info("This is a test log message.");
    }
}

import org.jgrapht.Graph;
import org.jgrapht.graph.DefaultEdge;
import org.jgrapht.generate.BipartiteGraphGenerator;
import org.jgrapht.generate.SimpleGraphGeneratorBase;

import java.util.HashMap;
import java.util.Map;

public class BipartiteGraphCreator<V, E extends DefaultEdge> extends SimpleGraphGeneratorBase<V, E> implements GraphGenerator<V, E, Map<String, V>> {

    private final int partitionOneSize;
    private final int partitionTwoSize;

    public BipartiteGraphCreator(int partitionOneSize, int partitionTwoSize) {
        this.partitionOneSize = partitionOneSize;
        this.partitionTwoSize = partitionTwoSize;
    }

    @Override
    public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
        if (resultMap == null) {
            resultMap = new HashMap<>();
        }

        BipartiteGraphGenerator<V, E> bipartiteGraphGenerator = new BipartiteGraphGenerator<>(partitionOneSize, partitionTwoSize);
        bipartiteGraphGenerator.generateGraph(target, resultMap, vertexFactory, edgeFactory);

        for (int i = 0; i < partitionOneSize; i++) {
            V vertex = target.vertexSet().toArray((V[]) new Object[0])[i];
            resultMap.put("Partition1_" + i, vertex);
        }

        for (int i = 0; i < partitionTwoSize; i++) {
            V vertex = target.vertexSet().toArray((V[]) new Object[0])[partitionOneSize + i];
            resultMap.put("Partition2_" + i, vertex);
        }
    }

    public static void main(String[] args) {
        // Example usage
        Graph<String, DefaultEdge> graph = new org.jgrapht.graph.SimpleGraph<>(DefaultEdge.class);
        Map<String, String> resultMap = new HashMap<>();
        BipartiteGraphCreator<String, DefaultEdge> generator = new BipartiteGraphCreator<>(3, 2);
        generator.generateGraph(graph, resultMap);

        System.out.println("Graph vertices: " + graph.vertexSet());
        System.out.println("Graph edges: " + graph.edgeSet());
        System.out.println("Result map: " + resultMap);
    }
}

import java.nio.ByteBuffer;

public class ByteFinder {
    protected int findByte(byte value, int pos) {
        byte[] buffer = {(byte) 0x01, (byte) 0x02, (byte) 0x03, (byte) 0x04, (byte) 0x05}; // Example buffer
        if (pos < 0 || pos >= buffer.length) {
            return -1;
        }
        for (int i = pos; i < buffer.length; i++) {
            if (buffer[i] == value) {
                return i;
            }
        }
        return -1;
    }

    public static void main(String[] args) {
        ByteFinder finder = new ByteFinder();
        System.out.println(finder.findByte((byte) 0x03, 1)); // Output: 2
        System.out.println(finder.findByte((byte) 0x06, 0)); // Output: -1
    }
}

