import java.util.HashMap;
import java.util.Map;

public class SymbolTable {
    private Map<String, Integer> typeTable;
    private int nextIndex;

    public SymbolTable() {
        typeTable = new HashMap<>();
        nextIndex = 0;
    }

    /**
     * Adds a type in the type table of this symbol table. Does nothing if the type table already contains a similar type.
     * @param value an internal class name.
     * @return the index of a new or already existing type Symbol with the given value.
     */
    public int addType(final String value) {
        if (typeTable.containsKey(value)) {
            return typeTable.get(value);
        } else {
            typeTable.put(value, nextIndex);
            return nextIndex++;
        }
    }

    public static void main(String[] args) {
        SymbolTable symbolTable = new SymbolTable();
        System.out.println(symbolTable.addType("String")); // Output: 0
        System.out.println(symbolTable.addType("Integer")); // Output: 1
        System.out.println(symbolTable.addType("String")); // Output: 0
    }
}

import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;

public class TypeResolver {

    /** 
     * Resolves the arguments for the  {@code genericType} using the type variable information for the{@code targetType}. Returns  {@code null} if {@code genericType} is not parameterized or ifarguments cannot be resolved.
     */
    public static Class<?>[] resolveArguments(Type genericType, Class<?> targetType) {
        if (genericType instanceof ParameterizedType) {
            ParameterizedType parameterizedType = (ParameterizedType) genericType;
            Type[] actualTypeArguments = parameterizedType.getActualTypeArguments();
            Class<?>[] result = new Class<?>[actualTypeArguments.length];
            for (int i = 0; i < actualTypeArguments.length; i++) {
                Type typeArgument = actualTypeArguments[i];
                if (typeArgument instanceof Class) {
                    result[i] = (Class<?>) typeArgument;
                } else {
                    return null; // Cannot resolve type argument
                }
            }
            return result;
        }
        return null; // Not parameterized
    }

    public static void main(String[] args) {
        // Example usage
        Type genericType = new ExampleTypeToken<List<String>>() {}.getType();
        Class<?>[] resolvedArguments = resolveArguments(genericType, ExampleTypeToken.class);
        if (resolvedArguments != null) {
            for (Class<?> clazz : resolvedArguments) {
                System.out.println(clazz);
            }
        } else {
            System.out.println("Arguments could not be resolved or type is not parameterized.");
        }
    }
}

class ExampleTypeToken<T> {
    private final Type type;

    protected ExampleTypeToken() {
        Type superClass = getClass().getGenericSuperclass();
        if (superClass instanceof Class) {
            throw new RuntimeException("Missing type parameter.");
        }
        this.type = ((ParameterizedType) superClass).getActualTypeArguments()[0];
    }

    public Type getType() {
        return type;
    }
}

import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class MetricsCache<METRICS extends Map<String, Integer>> {
    private final METRICS cache;

    public MetricsCache(METRICS initialData) {
        this.cache = initialData;
    }

    @Override
    public void accept(final METRICS data) {
        for (Map.Entry<String, Integer> entry : data.entrySet()) {
            cache.merge(entry.getKey(), entry.getValue(), Integer::sum);
        }
    }

    public METRICS getCache() {
        return cache;
    }

    public static void main(String[] args) {
        Map<String, Integer> initialData = new ConcurrentHashMap<>();
        initialData.put("metric1", 10);
        initialData.put("metric2", 20);

        MetricsCache<Map<String, Integer>> metricsCache = new MetricsCache<>(initialData);

        Map<String, Integer> newData = new ConcurrentHashMap<>();
        newData.put("metric2", 5);
        newData.put("metric3", 15);

        metricsCache.accept(newData);

        System.out.println(metricsCache.getCache()); // Output: {metric1=10, metric2=25, metric3=15}
    }
}

