import java.util.HashMap;
import java.util.Map;

public class MappingsDiff {

    public static class Mappings {
        private Map<String, Object> fields;

        public Mappings(Map<String, Object> fields) {
            this.fields = fields;
        }

        public Map<String, Object> getFields() {
            return fields;
        }
    }

    public Mappings diffStructure(String tableName, Mappings mappings) {
        // Example historical mappings
        Map<String, Object> historicalMappings = new HashMap<>();
        Map<String, Object> historicalFields = new HashMap<>();
        historicalFields.put("field1", "type1");
        historicalFields.put("field2", "type2");
        historicalFields.put("_source", "sourceConfig");
        historicalMappings.put(tableName, historicalFields);

        // Get the current mappings fields
        Map<String, Object> currentFields = mappings.getFields();

        // Create a result map to store the differences
        Map<String, Object> diffFields = new HashMap<>(historicalFields);

        // Remove fields that exist in the current mappings and the _source field
        currentFields.keySet().forEach(diffFields::remove);
        diffFields.remove("_source");

        return new Mappings(diffFields);
    }

    public static void main(String[] args) {
        MappingsDiff diff = new MappingsDiff();

        // Example current mappings
        Map<String, Object> currentFields = new HashMap<>();
        currentFields.put("field1", "type1");
        currentFields.put("field3", "type3");
        Mappings currentMappings = new Mappings(currentFields);

        Mappings result = diff.diffStructure("exampleTable", currentMappings);

        System.out.println("Difference in mappings: " + result.getFields());
    }
}

