import java.nio.ByteBuffer;
import java.nio.ByteOrder;

public class ClassReader {
    private byte[] classFileBuffer;

    public ClassReader(byte[] classFileBuffer) {
        this.classFileBuffer = classFileBuffer;
    }

    /**
     * Reads a signed long value in this  {@link ClassReader}. <i>This method is intended for  {@link Attribute} sub classes, and is normally not needed by class generators or adapters.</i>
     * @param offset the start offset of the value to be read in this {@link ClassReader}.
     * @return the read value.
     */
    public long readLong(final int offset) {
        ByteBuffer buffer = ByteBuffer.wrap(classFileBuffer, offset, 8);
        buffer.order(ByteOrder.BIG_ENDIAN);
        return buffer.getLong();
    }

    public static void main(String[] args) {
        // Example usage
        byte[] classFileBuffer = new byte[8];
        // Assuming we fill classFileBuffer with some bytes representing a long value
        classFileBuffer[0] = 0x00;
        classFileBuffer[1] = 0x00;
        classFileBuffer[2] = 0x00;
        classFileBuffer[3] = 0x00;
        classFileBuffer[4] = 0x00;
        classFileBuffer[5] = 0x00;
        classFileBuffer[6] = (byte) 0x80;
        classFileBuffer[7] = 0x00;

        ClassReader reader = new ClassReader(classFileBuffer);
        long value = reader.readLong(0);
        System.out.println("Read long value: " + value);
    }
}

import java.util.Arrays;

public class ArrayComparator {
    private byte[] internalArray;

    public ArrayComparator(byte[] internalArray) {
        this.internalArray = internalArray;
    }

    /** 
     * Returns true if the contents of the internal array and the provided array match.
     */
    public boolean equals(final byte[] data, int offset, final int len) {
        if (data == null || len < 0 || offset < 0 || offset + len > data.length) {
            return false;
        }
        if (internalArray == null) {
            return len == 0;
        }
        if (internalArray.length != len) {
            return false;
        }
        for (int i = 0; i < len; i++) {
            if (internalArray[i] != data[offset + i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        ArrayComparator comparator = new ArrayComparator(new byte[]{1, 2, 3, 4, 5});
        byte[] testData = new byte[]{0, 1, 2, 3, 4, 5};
        System.out.println(comparator.equals(testData, 1, 5)); // true
        System.out.println(comparator.equals(testData, 0, 5)); // false
    }
}

