import java.io.*;
import java.net.*;
import java.util.*;

public class TelnetServer {
    private List<Socket> clients = new ArrayList<>();

    public synchronized void addClient(Socket client) {
        clients.add(client);
    }

    public synchronized void removeClient(Socket client) {
        clients.remove(client);
    }

    public synchronized void send(final String message) {
        for (Socket client : clients) {
            try {
                OutputStream output = client.getOutputStream();
                PrintWriter writer = new PrintWriter(output, true);
                writer.println(message);
            } catch (IOException e) {
                e.printStackTrace();
                removeClient(client);
            }
        }
    }

    public static void main(String[] args) {
        // Example usage
        TelnetServer server = new TelnetServer();
        try (ServerSocket serverSocket = new ServerSocket(12345)) {
            System.out.println("Server is listening on port 12345");
            while (true) {
                Socket socket = serverSocket.accept();
                System.out.println("New client connected");
                server.addClient(socket);
                server.send("Hello, client! You are connected to the server.");
            }
        } catch (IOException ex) {
            System.out.println("Server exception: " + ex.getMessage());
            ex.printStackTrace();
        }
    }
}

import java.util.Arrays;

public class ArrayUtils {
    public static final Boolean[] EMPTY_BOOLEAN_ARRAY = new Boolean[0];

    /** 
     * <p>Defensive programming technique to change a <code>null</code> reference to an empty one.</p> 
     * <p>This method returns an empty array for a <code>null</code> input array.</p> 
     * <p>As a memory optimizing technique an empty array passed in will be overridden with the empty <code>public static</code> references in this class.</p>
     * @param array  the array to check for <code>null</code> or empty
     * @return the same array, <code>public static</code> empty array if <code>null</code> or empty input
     * @since 2.5
     */
    public static Boolean[] nullToEmpty(final Boolean[] array) {
        if (array == null || array.length == 0) {
            return EMPTY_BOOLEAN_ARRAY;
        }
        return array;
    }

    public static void main(String[] args) {
        Boolean[] testArray = null;
        Boolean[] result = nullToEmpty(testArray);
        System.out.println("Result for null input: " + Arrays.toString(result));

        Boolean[] emptyArray = {};
        result = nullToEmpty(emptyArray);
        System.out.println("Result for empty input: " + Arrays.toString(result));

        Boolean[] nonEmptyArray = {true, false};
        result = nullToEmpty(nonEmptyArray);
        System.out.println("Result for non-empty input: " + Arrays.toString(result));
    }
}

