import java.time.LocalDate;
import java.time.format.DateTimeFormatter;

public class TimeBucketCompressor {

    static long compressTimeBucket(long timeBucket, int dayStep) {
        DateTimeFormatter formatter = DateTimeFormatter.ofPattern("yyyyMMdd");
        LocalDate date = LocalDate.parse(String.valueOf(timeBucket), formatter);
        int dayOfMonth = date.getDayOfMonth();
        int newDayOfMonth = ((dayOfMonth - 1) / dayStep) * dayStep + 1;
        LocalDate newDate = date.withDayOfMonth(newDayOfMonth);
        return Long.parseLong(newDate.format(formatter));
    }

    public static void main(String[] args) {
        System.out.println(compressTimeBucket(20000105, 11)); // Output: 20000101
        System.out.println(compressTimeBucket(20000115, 11)); // Output: 20000112
        System.out.println(compressTimeBucket(20000123, 11)); // Output: 20000123
    }
}

import java.nio.charset.StandardCharsets;

public class UTF8SizeCalculator {

    /** 
     * Computes the size of the utf8 string beginning at the specified  {@code index} with the specified {@code length}.
     */
    public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
        if (str == null) {
            throw new IllegalArgumentException("Input string cannot be null");
        }
        if (index < 0 || len < 0 || index + len > str.length()) {
            throw new IllegalArgumentException("Invalid index or length");
        }

        final String substring = str.subSequence(index, index + len).toString();
        return substring.getBytes(StandardCharsets.UTF_8).length;
    }

    public static void main(String[] args) {
        // Example usage
        CharSequence str = "Hello, 世界";
        int index = 7;
        int len = 2;
        int utf8Size = computeUTF8Size(str, index, len);
        System.out.println("UTF-8 Size: " + utf8Size);
    }
}

