import java.util.HashSet;
import java.util.Set;

public class Graph<V, E> {
    private Set<Edge<V, E>> edges;

    public Graph(Set<Edge<V, E>> edges) {
        this.edges = edges;
    }

    private Set<V> initVisibleVertices() {
        Set<V> visibleVertices = new HashSet<>();
        for (Edge<V, E> edge : edges) {
            visibleVertices.add(edge.getSource());
            visibleVertices.add(edge.getTarget());
        }
        return visibleVertices;
    }

    public static class Edge<V, E> {
        private V source;
        private V target;
        private E label;

        public Edge(V source, V target, E label) {
            this.source = source;
            this.target = target;
            this.label = label;
        }

        public V getSource() {
            return source;
        }

        public V getTarget() {
            return target;
        }

        public E getLabel() {
            return label;
        }
    }

    public static void main(String[] args) {
        Set<Edge<String, String>> edges = new HashSet<>();
        edges.add(new Edge<>("A", "B", "e1"));
        edges.add(new Edge<>("B", "C", "e2"));
        edges.add(new Edge<>("A", "C", "e3"));

        Graph<String, String> graph = new Graph<>(edges);
        Set<String> visibleVertices = graph.initVisibleVertices();
        System.out.println(visibleVertices); // Output: [A, B, C]
    }
}

