import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[10];
        this.size = 0;
    }

    public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
        if (byteLength == 0) {
            return this;
        }

        ensureCapacity(size + byteLength);

        if (byteArrayValue == null) {
            Arrays.fill(data, size, size + byteLength, (byte) 0);
        } else {
            System.arraycopy(byteArrayValue, byteOffset, data, size, byteLength);
        }

        size += byteLength;
        return this;
    }

    private void ensureCapacity(int capacity) {
        if (capacity > data.length) {
            int newCapacity = Math.max(data.length * 2, capacity);
            data = Arrays.copyOf(data, newCapacity);
        }
    }

    public static void main(String[] args) {
        ByteVector byteVector = new ByteVector();
        byte[] bytes = {1, 2, 3, 4, 5};
        byteVector.putByteArray(bytes, 1, 3);
        System.out.println(Arrays.toString(byteVector.data)); // Output: [2, 3, 4, 0, 0, 0, 0, 0, 0, 0]
    }
}

