import java.util.Properties;

public class PropertySubstitutor {
    public static String findAndSubst(String key, Properties props) {
        String value = props.getProperty(key);
        if (value == null) {
            return null;
        }
        // Perform variable substitution
        // This is a simple implementation that assumes variables are in the form ${var}
        StringBuilder result = new StringBuilder();
        int start = 0;
        int openIndex;
        while ((openIndex = value.indexOf("${", start)) != -1) {
            int closeIndex = value.indexOf("}", openIndex + 2);
            if (closeIndex == -1) {
                break; // Malformed variable
            }
            result.append(value, start, openIndex);
            String varName = value.substring(openIndex + 2, closeIndex);
            String varValue = props.getProperty(varName);
            if (varValue != null) {
                result.append(varValue);
            } else {
                result.append("${").append(varName).append("}"); // Keep original if not found
            }
            start = closeIndex + 1;
        }
        result.append(value.substring(start));
        return result.toString();
    }

    public static void main(String[] args) {
        Properties props = new Properties();
        props.setProperty("greeting", "Hello, ${name}!");
        props.setProperty("name", "World");
        System.out.println(findAndSubst("greeting", props)); // Output: Hello, World!
    }
}

