        System.out.println(endsWith("HelloWorld", "World", false)); // true
        System.out.println(endsWith("HelloWorld", "world", false)); // false
        System.out.println(endsWith(null, null, true)); // true
        System.out.println(endsWith(null, "World", true)); // false
        System.out.println(endsWith("HelloWorld", null, true)); // false
    }
}

import java.net.URI;
import java.net.URISyntaxException;
import java.util.ArrayList;
import java.util.List;

public class PathSegmentImpl {
    private String path;

    public PathSegmentImpl(String path) {
        this.path = path;
    }

    public String getPath() {
        return path;
    }

    public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        List<PathSegmentImpl> pathSegments = new ArrayList<>();
        String path = u.getPath();

        if (path == null || path.isEmpty()) {
            return pathSegments;
        }

        // If the path is absolute, ignore the leading '/'
        if (path.startsWith("/")) {
            path = path.substring(1);
        }

        String[] segments = path.split("/");

        for (String segment : segments) {
            if (decode) {
                try {
                    segment = java.net.URLDecoder.decode(segment, "UTF-8");
                } catch (Exception e) {
                    // Handle decoding exception if necessary
                }
            }
            pathSegments.add(new PathSegmentImpl(segment));
        }

        return pathSegments;
    }

    public static void main(String[] args) {
        try {
            URI uri = new URI("http://example.com/path/to/resource");
            List<PathSegmentImpl> segments = decodePath(uri, true);
            for (PathSegmentImpl segment : segments) {
                System.out.println(segment.getPath());
            }
        } catch (URISyntaxException e) {
            e.printStackTrace();
        }
    }
}

