import java.util.Stack;

public class NDC {
    private static final Stack<String> stack = new Stack<>();

    /** 
     * Looks at the last diagnostic context at the top of this NDC without removing it. <p>The returned value is the value that was pushed last. If no context is available, then the empty string "" is returned.
     * @return String The innermost diagnostic context.
     */
    public static String peek() {
        if (stack.isEmpty()) {
            return "";
        }
        return stack.peek();
    }

    public static void main(String[] args) {
        // Example usage
        System.out.println(peek()); // Should print ""
        stack.push("Context1");
        System.out.println(peek()); // Should print "Context1"
        stack.push("Context2");
        System.out.println(peek()); // Should print "Context2"
    }
}

