import java.io.InputStream;
import java.io.IOException;

public class VarintReader {
    private InputStream input;

    public VarintReader(InputStream input) {
        this.input = input;
    }

    public long readRawVarint64() throws IOException {
        long result = 0;
        int shift = 0;
        byte b;
        do {
            if (shift >= 64) {
                throw new IOException("Invalid varint");
            }
            b = (byte) input.read();
            result |= (long) (b & 0x7F) << shift;
            shift += 7;
        } while ((b & 0x80) != 0);
        return result;
    }

    public static void main(String[] args) {
        // Example usage
        byte[] testData = {0x96, 0x01}; // Example Varint encoding for the number 150
        VarintReader reader = new VarintReader(new java.io.ByteArrayInputStream(testData));
        try {
            long value = reader.readRawVarint64();
            System.out.println("Read value: " + value);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

