        List<File> classpathFiles = new ArrayList<>();
        URLClassLoader classLoader = (URLClassLoader) ClassLoader.getSystemClassLoader();
        URL[] urls = classLoader.getURLs();
        for (URL url : urls) {
            classpathFiles.add(new File(url.getPath()));
        }
        return classpathFiles.toArray(new File[0]);
    }

    public static void main(String[] args) {
        File[] classpath = classPath();
        for (File file : classpath) {
            System.out.println(file.getAbsolutePath());
        }
    }
}

import java.util.Arrays;

public class ArrayUtils {
    private static String[] copyStrings(final String[] src) {
        if (src == null) {
            return null;
        }
        String[] dst = new String[src.length];
        for (int i = 0; i < src.length; i++) {
            dst[i] = src[i] != null ? src[i].toLowerCase() : null;
        }
        return dst;
    }

    public static void main(String[] args) {
        String[] src = {"Hello", "WORLD", "Java", "PROGRAMMING"};
        String[] dst = copyStrings(src);
        System.out.println(Arrays.toString(dst)); // Output: [hello, world, java, programming]
    }
}

