import java.util.Comparator;

public class DoubleComparator implements Comparator<Double> {
    @Override
    public int compare(Double o1, Double o2) {
        if (o1 == null && o2 == null) {
            return 0;
        }
        if (o1 == null) {
            return -1;
        }
        if (o2 == null) {
            return 1;
        }
        return Double.compare(o1, o2);
    }

    public static void main(String[] args) {
        DoubleComparator comparator = new DoubleComparator();
        System.out.println(comparator.compare(1.0, 2.0)); // -1
        System.out.println(comparator.compare(2.0, 1.0)); // 1
        System.out.println(comparator.compare(1.0, 1.0)); // 0
        System.out.println(comparator.compare(null, 1.0)); // -1
        System.out.println(comparator.compare(1.0, null)); // 1
        System.out.println(comparator.compare(null, null)); // 0
    }
}

