import java.io.DataOutput;
import java.io.IOException;

public class BufferWriter {

    /**
     * Writes the contents of the  {@link LinkedBuffer} into the {@link DataOutput}.
     * @return the total content size of the buffer.
     */
    public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
        int totalSize = 0;
        while (node != null) {
            int size = node.size;
            out.write(node.buffer, 0, size);
            totalSize += size;
            node = node.next;
        }
        return totalSize;
    }

    // Assuming LinkedBuffer is defined as follows:
    public static class LinkedBuffer {
        public final byte[] buffer;
        public int size;
        public LinkedBuffer next;

        public LinkedBuffer(int bufferSize) {
            this.buffer = new byte[bufferSize];
            this.size = 0;
            this.next = null;
        }
    }

    // Example usage
    public static void main(String[] args) throws IOException {
        // Create a simple LinkedBuffer for demonstration
        LinkedBuffer buffer = new LinkedBuffer(10);
        buffer.size = 5;
        for (int i = 0; i < 5; i++) {
            buffer.buffer[i] = (byte) i;
        }

        // Create a DataOutput stream, for example using ByteArrayOutputStream
        java.io.ByteArrayOutputStream byteArrayOutputStream = new java.io.ByteArrayOutputStream();
        DataOutput dataOutput = new java.io.DataOutputStream(byteArrayOutputStream);

        // Write the buffer to the DataOutput
        int totalSize = writeTo(dataOutput, buffer);

        // Verify the result
        System.out.println("Total size written: " + totalSize);
        System.out.println("Written bytes: " + java.util.Arrays.toString(byteArrayOutputStream.toByteArray()));
    }
}

