import java.io.IOException;
import java.io.InputStream;
import java.util.Arrays;

public class ClassFileBuffer {
    private byte[] buffer;
    private int length;

    public void readFrom(final InputStream in) throws IOException {
        if (in == null) {
            throw new IllegalArgumentException("InputStream cannot be null");
        }
        try (InputStream input = in) {
            buffer = new byte[1024];
            length = 0;
            int n;
            while ((n = input.read(buffer, length, buffer.length - length)) != -1) {
                length += n;
                if (length >= buffer.length) {
                    buffer = Arrays.copyOf(buffer, buffer.length * 2);
                }
            }
            buffer = Arrays.copyOf(buffer, length);
        }
    }

    public static void main(String[] args) {
        // Example usage
        try (InputStream inputStream = ClassFileBuffer.class.getResourceAsStream("/example.class")) {
            ClassFileBuffer classFileBuffer = new ClassFileBuffer();
            classFileBuffer.readFrom(inputStream);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

