import java.lang.reflect.Type;

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    if (type != Character.class && type != Character.TYPE) {
        throw new IllegalArgumentException("Type must be Character or char");
    }
    if (value == null) {
        throw new IllegalArgumentException("Value cannot be null");
    }
    if (value instanceof Character) {
        return value;
    }
    if (value instanceof String) {
        String str = (String) value;
        if (str.length() != 1) {
            throw new IllegalArgumentException("String must be of length 1 to convert to Character");
        }
        return str.charAt(0);
    }
    throw new IllegalArgumentException("Cannot convert " + value.getClass().getName() + " to Character");
}

