import java.util.Collection;

public class Finder {
    public static Object findFirstMatch(Collection source, Collection candidates) {
        for (Object candidate : candidates) {
            if (source.contains(candidate)) {
                return candidate;
            }
        }
        return null;
    }

    public static void main(String[] args) {
        // Example usage
        Collection<String> source = List.of("apple", "banana", "cherry");
        Collection<String> candidates = List.of("kiwi", "banana", "mango");

        Object result = findFirstMatch(source, candidates);
        System.out.println(result); // Output: banana
    }
}

import java.lang.Character;

public class TrimUtility {
    /** 
     * Trim trailing whitespace from the given String.
     * @param str the String to check
     * @return the trimmed String
     * @see java.lang.Character#isWhitespace
     */
    public static String trimTrailingWhitespace(String str) {
        if (str == null || str.isEmpty()) {
            return str;
        }
        int len = str.length();
        int st = 0;
        int off = len;
        while ((st < len) && Character.isWhitespace(str.charAt(off - 1))) {
            off--;
        }
        return ((st > 0) || (off < len)) ? str.substring(0, off) : str;
    }

    public static void main(String[] args) {
        System.out.println(trimTrailingWhitespace("Hello World   ")); // Output: "Hello World"
        System.out.println(trimTrailingWhitespace("   ")); // Output: ""
        System.out.println(trimTrailingWhitespace("NoTrailingSpace")); // Output: "NoTrailingSpace"
        System.out.println(trimTrailingWhitespace("")); // Output: ""
        System.out.println(trimTrailingWhitespace(null)); // Output: null
    }
}

