import java.lang.Character;

public class DigitInterpreter {
    private static int digitValue(final char c) {
        if (c >= '0' && c <= '9') {
            return c - '0';
        } else if (c >= 'A' && c <= 'Z') {
            return c - 'A' + 10;
        } else if (c >= 'a' && c <= 'z') {
            return c - 'a' + 10;
        } else {
            throw new IllegalArgumentException("Character is not a valid digit in any base up to 36: " + c);
        }
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(digitValue('0')); // 0
        System.out.println(digitValue('9')); // 9
        System.out.println(digitValue('A')); // 10
        System.out.println(digitValue('Z')); // 35
        System.out.println(digitValue('a')); // 10
        System.out.println(digitValue('z')); // 35
    }
}

