import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class UnescapeJava {

    public static String unescapeJava(String str) throws Exception {
        if (str == null) {
            return null;
        }

        StringBuilder output = new StringBuilder();
        int length = str.length();
        for (int i = 0; i < length; i++) {
            char currentChar = str.charAt(i);
            if (currentChar == '\\') {
                if (i + 1 < length) {
                    char nextChar = str.charAt(i + 1);
                    switch (nextChar) {
                        case 'b': output.append('\b'); break;
                        case 't': output.append('\t'); break;
                        case 'n': output.append('\n'); break;
                        case 'f': output.append('\f'); break;
                        case 'r': output.append('\r'); break;
                        case '"': output.append('\"'); break;
                        case '\'': output.append('\''); break;
                        case '\\': output.append('\\'); break;
                        case 'u':
                            if (i + 5 < length) {
                                int codePoint = Integer.parseInt(str.substring(i + 2, i + 6), 16);
                                output.append((char) codePoint);
                                i += 5; // Skip the next 5 characters as they are part of the Unicode
                            } else {
                                throw new Exception("Invalid Unicode escape sequence");
                            }
                            break;
                        default:
                            throw new Exception("Invalid escape sequence: \\" + nextChar);
                    }
                    i++; // We have already processed the next character
                } else {
                    throw new Exception("Trailing backslash at the end of the string");
                }
            } else {
                output.append(currentChar);
            }
        }
        return output.toString();
    }

    public static void main(String[] args) {
        try {
            System.out.println(unescapeJava("Hello\\nWorld"));
            System.out.println(unescapeJava("This\\tis\\ta\\ttest"));
            System.out.println(unescapeJava("Unicode\\u0041\\u0042\\u0043"));
            System.out.println(unescapeJava("NormalString"));
        } catch (Exception e) {
            e.printStackTrace();
        }
    }
}

