public class CHARSETTranslator {

    private static final Map<String, String> MIME_TO_JAVA_CHARSETS;

    static {
        MIME_TO_JAVA_CHARSETS = new HashMap<>();
        MIME_TO_JAVA_CHARSETS.put("us-ascii", StandardCharsets.US_ASCII.name().toLowerCase());
        MIME_TO_JAVA_CHARSETS.put("iso-8859-1", StandardCharsets.ISO_8859_1.name().toLowerCase());
        MIME_TO_JAVA_CHARSETS.put("utf-8", StandardCharsets.UTF_8.name().toLowerCase());
        MIME_TO_JAVA_CHARSETS.put("utf-16", StandardCharsets.UTF_16.name().toLowerCase());
        MIME_TO_JAVA_CHARSETS.put("utf-16be", StandardCharsets.UTF_16BE.name().toLowerCase());
