                    Object value = propertyDescriptor.getReadMethod().invoke(this);
                    values.add(value);
                }
            }
            return Collections.unmodifiableCollection(values);
        } catch (IntrospectionException | IllegalAccessException | InvocationTargetException e) {
            throw new RuntimeException("Failed to retrieve bean values", e);
        }
    }

    // Example properties for demonstration
    private String exampleProperty1 = "value1";
    private int exampleProperty2 = 42;

    public String getExampleProperty1() {
        return exampleProperty1;
    }

    public int getExampleProperty2() {
        return exampleProperty2;
    }

    public static void main(String[] args) {
        BeanMapValues bean = new BeanMapValues();
        Collection<Object> values = bean.values();
        System.out.println(values);
    }
}

