import java.util.List;
import java.util.ArrayList;

public class ShardingKeyChecker {

    private List<Integer> shardingKeyIndices;

    public ShardingKeyChecker(List<Integer> shardingKeyIndices) {
        this.shardingKeyIndices = shardingKeyIndices;
    }

    /** 
     * @param modelName model name of the entity
     * @throws IllegalStateException if sharding key indices are not continuous
     */
    private void check(String modelName) throws IllegalStateException {
        if (shardingKeyIndices == null || shardingKeyIndices.isEmpty()) {
            return;
        }

        for (int i = 1; i < shardingKeyIndices.size(); i++) {
            if (shardingKeyIndices.get(i) != shardingKeyIndices.get(i - 1) + 1) {
                throw new IllegalStateException("Sharding key indices are not continuous for model: " + modelName);
            }
        }
    }

    public static void main(String[] args) {
        ShardingKeyChecker checker = new ShardingKeyChecker(List.of(0, 1, 2, 3));
        checker.check("ModelA"); // Should not throw exception

        ShardingKeyChecker checker2 = new ShardingKeyChecker(List.of(0, 2, 3, 4));
        try {
            checker2.check("ModelB"); // Should throw exception
        } catch (IllegalStateException e) {
            System.out.println(e.getMessage());
        }
    }
}

