public class Graph {

    // Assuming a map to store the edges and their weights
    private Map<V, Map<V, Double>> adjacencyList;

    public Graph() {
        adjacencyList = new java.util.HashMap<>();
    }

    public void addEdge(V from, V to, double weight) {
        adjacencyList.computeIfAbsent(from, k -> new java.util.HashMap<>()).put(to, weight);
    }

    /** 
     * Compute the sum of the weights entering a vertex
     * @param v the vertex
     * @return the sum of the weights entering a vertex
     */
    public double vertexWeight(V v) {
        double sum = 0.0;
        for (Map<V, Double> edges : adjacencyList.values()) {
            if (edges.containsKey(v)) {
                sum += edges.get(v);
            }
        }
        return sum;
    }

    public static void main(String[] args) {
        Graph graph = new Graph();
        graph.addEdge("A", "B", 1.0);
        graph.addEdge("C", "B", 2.0);
        graph.addEdge("B", "D", 3.0);

        System.out.println("Weight entering B: " + graph.vertexWeight("B")); // Should print 3.0
    }
}

