public class CustomComparator implements Comparator<Object> {
    @Override
    public int compare(Object aObj1, Object aObj2) {
        if (aObj1 == null && aObj2 == null) {
            return 0;
        }
        if (aObj1 == null) {
            return -1;
        }
        if (aObj2 == null) {
            return 1;
        }
        if (aObj1 instanceof Comparable && aObj2 instanceof Comparable) {
            return ((Comparable) aObj1).compareTo(aObj2);
        }
        return aObj1.toString().compareTo(aObj2.toString());
    }

    public static void main(String[] args) {
        CustomComparator comparator = new CustomComparator();
        System.out.println(comparator.compare("apple", "banana"));
        System.out.println(comparator.compare(10, 20));
        System.out.println(comparator.compare(null, "test"));
        System.out.println(comparator.compare("test", null));
        System.out.println(comparator.compare(null, null));
    }
}

