import org.apache.logging.log4j.core.config.LoggerConfig;

public class AppenderRemover {

    public void removeAppender(String name) {
        LoggerContext context = LoggerContext.getContext(false);
        Configuration config = context.getConfiguration();
        LoggerConfig loggerConfig = config.getLoggerConfig(LoggerContext.ROOT_LOGGER_NAME);

        Appender appender = loggerConfig.getAppender(name);
        if (appender != null) {
            loggerConfig.removeAppender(name);
            appender.stop();
            config.removeAppender(name);
            context.updateLoggers();
        }
    }

    public static void main(String[] args) {
        AppenderRemover remover = new AppenderRemover();
        remover.removeAppender("Console");
    }
}

