public class AppenderLogger {
    private AppenderAttachableImpl aai = new AppenderAttachableImpl();

    public int appendLoopOnAppenders(LoggingEvent event) {
        int count = 0;
        for (Appender appender : aai.getAllAppenders()) {
            appender.doAppend(event);
            count++;
        }
        return count;
    }

    public void addAppender(Appender appender) {
        aai.addAppender(appender);
    }

    public static void main(String[] args) {
        AppenderLogger logger = new AppenderLogger();
        logger.addAppender(new org.apache.log4j.ConsoleAppender());
        logger.appendLoopOnAppenders(new LoggingEvent("LoggerName", Logger.getLogger("LoggerName"), org.apache.log4j.Level.INFO, "Test Message", null));
    }
}

