import org.jgrapht.Graph;
import org.jgrapht.GraphPath;
import org.jgrapht.alg.shortestpath.GraphWalk;
import org.jgrapht.graph.DefaultDirectedGraph;
import org.jgrapht.graph.DefaultEdge;

import java.util.*;

protected <V, E> GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour.isEmpty()) {
        return new GraphWalk<>(graph, null, null, new ArrayList<>(), 0);
    }

    Map<E, V> edgeTargets = new HashMap<>();
    Map<V, List<E>> incomingEdges = new HashMap<>();
    Map<V, List<E>> outgoingEdges = new HashMap<>();

    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        edgeTargets.put(edge, target);
        incomingEdges.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
        outgoingEdges.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
    }

    V startVertex = null;
    // Find a start vertex with no incoming edges or one incoming edge that is not in the tour
    for (V vertex : graph.vertexSet()) {
        List<E> inEdges = incomingEdges.getOrDefault(vertex, Collections.emptyList());
        List<E> outEdges = outgoingEdges.getOrDefault(vertex, Collections.emptyList());
        if (inEdges.size() != 1 || !tour.contains(inEdges.get(0))) {
            startVertex = vertex;
            break;
        }
    }

    if (startVertex == null) {
        // Fallback to any vertex if no clear start is found
        startVertex = graph.vertexSet().iterator().next();
    }

    List<E> edgeList = new ArrayList<>();
    V currentVertex = startVertex;
    while (!tour.isEmpty()) {
        List<E> outEdges = outgoingEdges.getOrDefault(currentVertex, Collections.emptyList());
        E nextEdge = null;
        for (E edge : outEdges) {
            if (tour.contains(edge)) {
                nextEdge = edge;
                break;
            }
        }
        if (nextEdge == null) {
            break;
        }
        edgeList.add(nextEdge);
        tour.remove(nextEdge);
        currentVertex = edgeTargets.get(nextEdge);
    }

    return new GraphWalk<>(graph, startVertex, currentVertex, edgeList, 0);
}

