import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class UnescapeUtil {

    /** 
     * Unescape a string DOT identifier.
     * @param input the input
     * @return the unescaped output
     */
    private String unescapeId(String input) {
        if (input == null) {
            return null;
        }
        // Assuming the escape character is a backslash (\) followed by the character to escape
        Pattern pattern = Pattern.compile("\\\\(.)");
        Matcher matcher = pattern.matcher(input);
        StringBuffer sb = new StringBuffer();
        while (matcher.find()) {
            matcher.appendReplacement(sb, matcher.group(1));
        }
        matcher.appendTail(sb);
        return sb.toString();
    }

    public static void main(String[] args) {
        UnescapeUtil util = new UnescapeUtil();
        System.out.println(util.unescapeId("hello\\,world")); // Output: hello,world
        System.out.println(util.unescapeId("this\\ is\\ a\\ test")); // Output: this is a test
    }
}

