public class BucketReloader {

    private void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
        Set<Integer> sourceBucket = bucketsByLabel.get(minLabel);
        Set<Integer> targetBucket = bucketsByLabel.get(0);

        for (Integer vertex : sourceBucket) {
            targetBucket.add(vertex);
            labels.set(vertex, 0);
        }

        sourceBucket.clear();
    }

    public static void main(String[] args) {
        // Example usage
        List<Set<Integer>> bucketsByLabel = List.of(
            new HashSet<>(Arrays.asList()), // Bucket 0
            new HashSet<>(Arrays.asList(1, 2, 3)), // Bucket 1
            new HashSet<>(Arrays.asList(4, 5)) // Bucket 2
        );

        List<Integer> labels = new ArrayList<>(Arrays.asList(0, 1, 1, 1, 2, 2));

        BucketReloader reloader = new BucketReloader();
        reloader.reload(bucketsByLabel, labels, 1);

        System.out.println("Bucket 0: " + bucketsByLabel.get(0)); // Should contain [1, 2, 3]
        System.out.println("Bucket 1: " + bucketsByLabel.get(1)); // Should be empty
        System.out.println("Labels: " + labels); // Should be [0, 0, 0, 0, 2, 2]
    }
}

