public class SubstringCounter {
    public static int countOccurrencesOf(String str, String sub) {
        if (Objects.isNull(str) || Objects.isNull(sub)) {
            return 0;
        }

        int count = 0;
        int index = 0;

        while ((index = str.indexOf(sub, index)) != -1) {
            count++;
            index += sub.length();
        }

        return count;
    }

    public static void main(String[] args) {
        System.out.println(countOccurrencesOf("hellohellohello", "hello")); // Output: 3
        System.out.println(countOccurrencesOf("hello", "ll")); // Output: 1
        System.out.println(countOccurrencesOf("hello", "world")); // Output: 0
        System.out.println(countOccurrencesOf(null, "hello")); // Output: 0
        System.out.println(countOccurrencesOf("hello", null)); // Output: 0
    }
}

