class ListNodeImpl<E> {
    E item;
    ListNodeImpl<E> next;
    ListNodeImpl<E> prev;

    ListNodeImpl(ListNodeImpl<E> prev, E element, ListNodeImpl<E> next) {
        this.item = element;
        this.next = next;
        this.prev = prev;
    }
}

public class LinkedListImpl<E> {
    private ListNodeImpl<E> first;
    private ListNodeImpl<E> last;
    private int size;

    private boolean unlink(ListNodeImpl<E> x) {
        if (x == null)
            return false;

        E element = x.item;
        ListNodeImpl<E> next = x.next;
        ListNodeImpl<E> prev = x.prev;

        if (prev == null) {
            first = next;
        } else {
            prev.next = next;
            x.prev = null;
        }

        if (next == null) {
            last = prev;
        } else {
            next.prev = prev;
            x.next = null;
        }

        x.item = null;
        size--;
        return true;
    }

    public static void main(String[] args) {
        LinkedListImpl<Integer> list = new LinkedListImpl<>();
        ListNodeImpl<Integer> node1 = new ListNodeImpl<>(null, 1, null);
        ListNodeImpl<Integer> node2 = new ListNodeImpl<>(node1, 2, null);
        node1.next = node2;
        list.first = node1;
        list.last = node2;
        list.size = 2;

        boolean removed = list.unlink(node2);
        System.out.println("Node removed: " + removed); // true
        System.out.println("List size: " + list.size); // 1
    }
}

