import java.io.IOException;
import java.io.Reader;
import java.io.StringReader;

public class TokenParser {

    private Reader reader;

    public TokenParser(String input) {
        this.reader = new StringReader(input);
    }

    /**
     * Parses out a token until any of the given terminators is encountered.
     * @param terminators the array of terminating characters. Any of these characters when encountered signify the end of the token
     * @return the token
     */
    private String parseToken(final char[] terminators) {
        StringBuilder token = new StringBuilder();
        int nextChar;

        try {
            while ((nextChar = reader.read()) != -1) {
                char c = (char) nextChar;
                boolean isTerminator = false;
                for (char terminator : terminators) {
                    if (c == terminator) {
                        isTerminator = true;
                        break;
                    }
                }
                if (isTerminator) {
                    break;
                }
                token.append(c);
            }
        } catch (IOException e) {
            e.printStackTrace();
        }

        return token.toString();
    }

    public static void main(String[] args) {
        TokenParser parser = new TokenParser("Hello, world!");
        char[] terminators = { ',', '!' };
        String token = parser.parseToken(terminators);
        System.out.println("Parsed token: " + token); // Output: Parsed token: Hello
    }
}

