public class StringUtils {
    /** 
     * Trim all occurrences of the supplied leading character from the given String.
     * @param str the String to check
     * @param leadingCharacter the leading character to be trimmed
     * @return the trimmed String
     */
    public static String trimLeadingCharacter(String str, char leadingCharacter) {
        if (str == null || str.isEmpty()) {
            return str;
        }

        int i = 0;
        while (i < str.length() && str.charAt(i) == leadingCharacter) {
            i++;
        }

        return str.substring(i);
    }

    public static void main(String[] args) {
        System.out.println(trimLeadingCharacter("xxxHello", 'x')); // Output: Hello
        System.out.println(trimLeadingCharacter("Hello", 'x'));    // Output: Hello
        System.out.println(trimLeadingCharacter("xx", 'x'));       // Output: (empty string)
        System.out.println(trimLeadingCharacter("", 'x'));         // Output: (empty string)
        System.out.println(trimLeadingCharacter(null, 'x'));       // Output: null
    }
}

