import javafx.util.Pair;

public class SuffixSumCalculator {

    private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        List<Integer> suffixSum = new ArrayList<>();
        long totalSum = 0;
        long sum = 0;

        for (int i = bounds.size() - 1; i >= 0; i--) {
            totalSum += bounds.get(i);
            sum += bounds.get(i);
            suffixSum.add(0, (int) sum);
        }

        return new Pair<>(suffixSum, totalSum);
    }

    public static void main(String[] args) {
        SuffixSumCalculator calculator = new SuffixSumCalculator();
        List<Integer> bounds = List.of(1, 2, 3, 4, 5);
        Pair<List<Integer>, Long> result = calculator.computeSuffixSum(bounds);
        System.out.println("Suffix Sum: " + result.getKey());
        System.out.println("Total Sum: " + result.getValue());
    }
}

import java.util.Arrays;

public class ArrayUtils {

    /** 
     * Reverses the order of the elements in the specified range within the given array.
     * @param < V > the type of elements in the array
     * @param arr the array
     * @param from the index of the first element (inclusive) inside the range to reverse
     * @param to the index of the last element (inclusive) inside the range to reverse
     */
    public static final <V> void reverse(V[] arr, int from, int to) {
        if (arr == null) {
            throw new IllegalArgumentException("Array must not be null");
        }
        if (from < 0 || to >= arr.length || from > to) {
            throw new IllegalArgumentException("Invalid from or to index");
        }
        while (from < to) {
            V temp = arr[from];
            arr[from] = arr[to];
            arr[to] = temp;
            from++;
            to--;
        }
    }

    public static void main(String[] args) {
        Integer[] array = {1, 2, 3, 4, 5, 6};
        reverse(array, 1, 4);
        System.out.println(Arrays.toString(array)); // Output: [1, 5, 4, 3, 2, 6]
    }
}

