        for (char c = '0'; c <= '9'; c++) {
            HEX_DIGITS.add(c);
        }
        for (char c = 'A'; c <= 'F'; c++) {
            HEX_DIGITS.add(c);
        }
        for (char c = 'a'; c <= 'f'; c++) {
            HEX_DIGITS.add(c);
        }
    }

    /**
     * Is this a hex digit?
     */
    private static boolean isHex(final char c) {
        return HEX_DIGITS.contains(c);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(isHex('A')); // true
        System.out.println(isHex('a')); // true
        System.out.println(isHex('0')); // true
        System.out.println(isHex('9')); // true
        System.out.println(isHex('G')); // false
        System.out.println(isHex('g')); // false
        System.out.println(isHex(' ')); // false
    }
}

