import java.util.Arrays;

public class StringSplitter {
    public static String[] split(String toSplit, String delimiter) {
        int delimiterIndex = toSplit.indexOf(delimiter);
        if (delimiterIndex == -1) {
            return null;
        }
        String beforeDelimiter = toSplit.substring(0, delimiterIndex);
        String afterDelimiter = toSplit.substring(delimiterIndex + delimiter.length());
        return new String[]{beforeDelimiter, afterDelimiter};
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(Arrays.toString(split("hello.world", "."))); // [hello, world]
        System.out.println(Arrays.toString(split("hello", "world"))); // null
        System.out.println(Arrays.toString(split("hello.world.example", "."))); // [hello, world.example]
    }
}

