public class TableSelector {

    /** 
     * Selects the specified row in the specified JTable and scrolls the specified JScrollPane to the newly selected row. More importantly, the call to repaint() delayed long enough to have the table properly paint the newly selected row which may be offscreen.
     * @param row should belong to the specified JScrollPane
     */
    public static void selectRow(int row, JTable table, JScrollPane pane) {
        if (row >= 0 && row < table.getRowCount()) {
            table.changeSelection(row, 0, false, false);
            pane.getViewport().scrollRectToVisible(table.getCellRect(row, 0, true));
            SwingUtilities.invokeLater(table::repaint);
        }
    }

    public static void main(String[] args) {
        // Example usage
        JFrame frame = new JFrame("JTable Example");
        DefaultTableModel model = new DefaultTableModel(new Object[]{"Column1", "Column2"}, 10);
        JTable table = new JTable(model);
        JScrollPane scrollPane = new JScrollPane(table);

        frame.add(scrollPane);
        frame.setSize(400, 300);
        frame.setDefaultCloseOperation(JFrame.EXIT_ON_CLOSE);
        frame.setVisible(true);

        // Select row 5
        selectRow(5, table, scrollPane);
    }
}

