import java.util.Arrays;

public class ArrayComparator {
    public static boolean arrayequals(byte[] a, byte[] b, int count) {
        if (a == null || b == null) {
            return a == b;
        }
        if (count < 0) {
            throw new IllegalArgumentException("Count cannot be negative");
        }
        int minLength = Math.min(a.length, b.length);
        count = Math.min(count, minLength);
        for (int i = 0; i < count; i++) {
            if (a[i] != b[i]) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        byte[] array1 = {1, 2, 3, 4, 5};
        byte[] array2 = {1, 2, 3, 4, 5};
        byte[] array3 = {1, 2, 3, 6, 5};

        System.out.println(arrayequals(array1, array2, 5)); // true
        System.out.println(arrayequals(array1, array3, 5)); // false
        System.out.println(arrayequals(array1, array2, 3)); // true
        System.out.println(arrayequals(array1, array2, 0)); // true
    }
}

import java.util.*;

public class NameAbbreviator {
    /** 
     * Abbreviate name.
     * @param buf buffer to append abbreviation.
     * @param nameStart start of name to abbreviate.
     */
    public void abbreviate(final int nameStart, final StringBuffer buf) {
        if (buf == null || nameStart < 0 || nameStart >= buf.length()) {
            return;
        }

        String name = buf.substring(nameStart);
        String[] parts = name.split("\\s+");
        if (parts.length > 1) {
            StringBuilder abbreviatedName = new StringBuilder();
            for (int i = 0; i < parts.length - 1; i++) {
                if (!parts[i].isEmpty()) {
                    abbreviatedName.append(parts[i].charAt(0)).append('.');
                }
            }
            abbreviatedName.append(parts[parts.length - 1]);
            buf.replace(nameStart, buf.length(), abbreviatedName.toString());
        }
    }

    public static void main(String[] args) {
        NameAbbreviator abbreviator = new NameAbbreviator();
        StringBuffer buffer = new StringBuffer("John Doe Smith");
        abbreviator.abbreviate(0, buffer);
        System.out.println(buffer.toString()); // Output: J.D.Smith
    }
}

