private List<Integer> computeLowerBounds(List<Integer> keys){
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return lowerBounds;
    }

    Collections.sort(keys);

    for (int i = 0; i < keys.size(); i++) {
        if (i == 0) {
            lowerBounds.add(Integer.MIN_VALUE);
        } else {
            lowerBounds.add(keys.get(i - 1));
        }
    }

    return lowerBounds;
}

import java.util.Stack;

public class FrameStack {

    private Stack<String> outputFrameStack = new Stack<>();

    /** 
     * Pops as many abstract types from the output frame stack as described by the given descriptor.
     * @param descriptor a type or method descriptor (in which case its argument types are popped).
     */
    private void pop(final String descriptor) {
        if (descriptor.startsWith("(")) {
            // Method descriptor, pop each argument type
            int i = 1;
            while (descriptor.charAt(i) != ')') {
                i = popType(descriptor, i);
            }
        } else {
            // Field descriptor, pop the described type
            popType(descriptor, 0);
        }
    }

    private int popType(String descriptor, int i) {
        switch (descriptor.charAt(i)) {
            case 'B': case 'C': case 'D': case 'F': case 'I': case 'J': case 'S': case 'Z':
                outputFrameStack.pop();
                i++;
                break;
            case 'L':
                // Object type, find the end of the class name
                while (descriptor.charAt(i) != ';') {
                    i++;
                }
                outputFrameStack.pop();
                i++;
                break;
            case '[':
                // Array type, skip to the type
                while (descriptor.charAt(i) == '[') {
                    i++;
                }
                i = popType(descriptor, i);
                break;
        }
        return i;
    }

    public static void main(String[] args) {
        FrameStack frameStack = new FrameStack();
        // Example usage
        frameStack.outputFrameStack.push("int");
        frameStack.outputFrameStack.push("double");
        frameStack.outputFrameStack.push("java.lang.String");
        frameStack.pop("(IDLjava/lang/String;)V");
        System.out.println(frameStack.outputFrameStack); // Should be empty
    }
}

