public class ArrayUtils {
    /** 
     * Returns a new array of Strings without null elements. Internal method used to normalize exclude lists (arrays and collections). Note that  {@link Arrays#sort(Object[])} will throw an {@link NullPointerException}if an array element is <code>null</code>.
     * @param array The array to check
     * @return The given array or a new array without null.
     */
    static String[] toNoNullStringArray(Object[] array) {
        if (array == null) {
            return new String[0];
        }

        List<String> list = new ArrayList<>();
        for (Object element : array) {
            if (element instanceof String && element != null) {
                list.add((String) element);
            }
        }

        return list.toArray(new String[0]);
    }

    public static void main(String[] args) {
        Object[] testArray = {"apple", null, "banana", "cherry", null};
        String[] result = toNoNullStringArray(testArray);

        for (String str : result) {
            System.out.println(str);
        }
    }
}

import java.io.File;

public class FilenameUtils {

    public static int indexOfExtension(String filename) {
        if (filename == null) {
            return -1;
        }

        int lastSeparatorIndex = indexOfLastSeparator(filename);
        int lastDotIndex = filename.lastIndexOf('.');

        if (lastDotIndex == -1 || (lastSeparatorIndex != -1 && lastDotIndex < lastSeparatorIndex)) {
            return -1;
        }

        return lastDotIndex;
    }

    private static int indexOfLastSeparator(String filename) {
        if (filename == null) {
            return -1;
        }

        int lastUnixPos = filename.lastIndexOf(File.separatorChar);
        int lastWindowsPos = filename.lastIndexOf('\\');

        return Math.max(lastUnixPos, lastWindowsPos);
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(indexOfExtension("file.txt")); // 4
        System.out.println(indexOfExtension("file")); // -1
        System.out.println(indexOfExtension("file.name.txt")); // 10
        System.out.println(indexOfExtension("folder/file.txt")); // 11
        System.out.println(indexOfExtension("folder\\file.txt")); // 11
        System.out.println(indexOfExtension("folder/file")); // -1
        System.out.println(indexOfExtension(null)); // -1
    }
}

