     * @param lastUpdateTime   the time of last update of the metrics
     * @param expiredThreshold represents the duration between last update time and the time point removing from cache in milliseconds.
     * @return true means this metrics should be removed from cache.
     */
    public boolean isExpired(long timestamp, long lastUpdateTime, long expiredThreshold) {
        return (timestamp - lastUpdateTime) > expiredThreshold;
