import java.text.MessageFormat;

public class SubstringMatcher {
    /** 
     * Returns  {@code true} if the given string matches the given substring at the given index, {@code false} otherwise.
     * @param str the original string (or StringBuilder)
     * @param index the index in the original string to start matching against
     * @param substring the substring to match at the given index
     * @return {@code true} if the given string matches the given substring at the given index, {@code false} otherwise.
     */
    public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
        if (str == null || substring == null || index < 0 || index + substring.length() > str.length()) {
            return false;
        }
        for (int i = 0; i < substring.length(); i++) {
            if (str.charAt(index + i) != substring.charAt(i)) {
                return false;
            }
        }
        return true;
    }

    public static void main(String[] args) {
        // Test cases
        System.out.println(substringMatch("hello world", 6, "world")); // true
        System.out.println(substringMatch("hello world", 6, "worl"));  // true
        System.out.println(substringMatch("hello world", 6, "wor"));   // true
        System.out.println(substringMatch("hello world", 6, "word"));  // false
        System.out.println(substringMatch("hello world", 0, "hello")); // true
        System.out.println(substringMatch("hello world", 11, "d"));    // false
        System.out.println(substringMatch("hello world", 10, ""));     // true
        System.out.println(substringMatch(null, 0, "test"));          // false
        System.out.println(substringMatch("hello world", 0, null));      // false
    }
}

import org.apache.log4j.AppenderSkeleton;
