import java.io.InputStream;
import java.io.IOException;

public class ProtocolMessageParser {
    private InputStream input;
    private int buffer = 0;
    private int bufferPos = 0;

    public ProtocolMessageParser(InputStream input) {
        this.input = input;
    }

    public int readTag() throws IOException {
        if (readRawByte() == -1) {
            return 0;
        }
        return readRawVarint32();
    }

    private int readRawByte() throws IOException {
        if (bufferPos == 0) {
            int n = input.read();
            if (n == -1) {
                return -1;
            }
            buffer = n;
            bufferPos = 1;
        }
        bufferPos--;
        return buffer & 0xFF;
    }

    private int readRawVarint32() throws IOException {
        int result = 0;
        int shift = 0;
        while (shift < 32) {
            int b = readRawByte();
            if (b == -1) {
                throw new IOException("Unexpected end of file");
            }
            result |= (b & 0x7F) << shift;
            if ((b & 0x80) == 0) {
                return result;
            }
            shift += 7;
        }
        throw new IOException("Malformed varint");
    }

    public static void main(String[] args) {
        // Example usage
        byte[] data = {0x08, 0x01}; // Example data containing a tag
        InputStream input = new java.io.ByteArrayInputStream(data);
        ProtocolMessageParser parser = new ProtocolMessageParser(input);
        try {
            int tag = parser.readTag();
            System.out.println("Read tag: " + tag);
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

import java.util.Arrays;

public class ByteVector {
    private byte[] data;
    private int size;

    public ByteVector() {
        this.data = new byte[10]; // Initial capacity
        this.size = 0;
    }

    final ByteVector put11(final int byteValue1, final int byteValue2) {
        ensureCapacity(size + 2);
        data[size++] = (byte) byteValue1;
        data[size++] = (byte) byteValue2;
        return this;
    }

    private void ensureCapacity(int capacity) {
        if (capacity > data.length) {
            int newCapacity = Math.max(data.length * 2, capacity);
            data = Arrays.copyOf(data, newCapacity);
        }
    }

    public static void main(String[] args) {
        ByteVector bv = new ByteVector();
        bv.put11(0x12, 0x34);
        System.out.println(Arrays.toString(bv.data)); // Output: [18, 52, 0, 0, 0, 0, 0, 0, 0, 0]
    }
}

import java.util.Objects;

public class ContentRangeBuilder {

    private long start;
    private long end;
    private long total;

    public ContentRangeBuilder(long start, long end, long total) {
        this.start = start;
        this.end = end;
        this.total = total;
    }

    /** 
     * Build the 'Content-Range' HTTP Header value.
     * @return 'Content-Range' value
     */
    private String buildContentRange() {
        Objects.requireNonNull(this, "ContentRangeBuilder cannot be null");
        return String.format("bytes %d-%d/%d", start, end, total);
    }

    public static void main(String[] args) {
        ContentRangeBuilder builder = new ContentRangeBuilder(0, 1023, 2048);
        System.out.println(builder.buildContentRange());
    }
}

